#include <iostream>
using namespace std;

using int64 = long long;
using int128 = __int128_t;

struct Point {
    int64 x, y;
};

int main() {
    Point a, b, c;
    cin >> a.x >> a.y >> b.x >> b.y >> c.x >> c.y;

    int128 abx = (int128)b.x - a.x;
    int128 aby = (int128)b.y - a.y;
    int128 bcx = (int128)c.x - b.x;
    int128 bcy = (int128)c.y - b.y;

    int128 ab2 = abx * abx + aby * aby;
    int128 bc2 = bcx * bcx + bcy * bcy;
    int128 cross = abx * bcy - aby * bcx;

    cout << (ab2 == bc2 && cross != 0 ? "Yes" : "No") << '\n';
    return 0;
}

#include <iostream>
using namespace std;

using LL = long long;
using i128 = __int128_t;

struct Point {
    LL x, y;
};

i128 squaredDistance(const Point& p, const Point& q) {
    i128 dx = (i128)p.x - q.x;
    i128 dy = (i128)p.y - q.y;
    return dx * dx + dy * dy;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    Point a, b, c;
    cin >> a.x >> a.y >> b.x >> b.y >> c.x >> c.y;

    i128 cross = ((i128)b.x - a.x) * ((i128)c.y - b.y)
               - ((i128)b.y - a.y) * ((i128)c.x - b.x);

    cout << (squaredDistance(a, b) == squaredDistance(b, c) && cross != 0
             ? "Yes\n" : "No\n");

    return 0;
}

