    int64 x, y;
};

i128 distanceSquared(const Point& p, const Point& q) {
    i128 dx = static_cast<i128>(p.x) - q.x;
    i128 dy = static_cast<i128>(p.y) - q.y;
    return dx * dx + dy * dy;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    Point a, b, c;
    cin >> a.x >> a.y >> b.x >> b.y >> c.x >> c.y;

    i128 cross = (static_cast<i128>(b.x) - a.x) * (c.y - b.y)
               - (static_cast<i128>(b.y) - a.y) * (c.x - b.x);

    cout << (distanceSquared(a, b) == distanceSquared(b, c) && cross != 0
             ? "Yes\n" : "No\n");

    return 0;
}

